import React, {useState} from 'react';
import LiveView from "./modules/LiveView";
import Recordings from "./modules/Recordings";
import {BottomNavigation, BottomNavigationAction, Box, Container, Icon, ThemeProvider} from "@mui/material";
import theme from "./MainTheme";


function GPSMap() {
    const [activeModule, setActiveModule] = useState("live"); // State to manage the active module

    return(

            <ThemeProvider theme={theme}>
                <Box sx={{backgroundColor: "primary.dark", minHeight: "100vh"}}>
                    <BottomNavigation
                        showLabels
                        value={activeModule}
                        onChange={(event, newValue) => {
                            setActiveModule(newValue);
                        }}
                        sx={{
                            backgroundColor: "primary.light",
                            padding: '2px 0 4px 0',

                        }}
                    >
                        <BottomNavigationAction
                            value="live"
                            label="En vivo" icon={<Icon>podcasts</Icon>}
                            sx={{
                                color: "primary.main", // Unselected color
                                '&.Mui-selected': {
                                    color: 'primary.dark', // Selected color
                                },
                            }}
                        />
                        <BottomNavigationAction
                            value="recordings"
                            label="Grabaciones"
                            icon={<Icon>receipt_long</Icon>}
                            sx={{
                                color: "primary.main", // Unselected color
                                '&.Mui-selected': {
                                    color: 'primary.dark', // Selected color
                                },
                            }}
                        />

                    </BottomNavigation>
                    <Container sx={{backgroundColor: "primary.dark", marginTop:"4%"}}>
                        {activeModule === "recordings" ?<Recordings/> : <></>}
                        {activeModule === "live" ? <LiveView/> : <></>}

                    </Container>


                </Box>

            </ThemeProvider>


        )

}

export default GPSMap;
